(OUT / '404.html').write_text(layout(*pages['404'][:2]), encoding='utf-8')
(OUT / 'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /workspace/\nDisallow: /auth/\n', encoding='utf-8')
print(f'Built {len(pages)} pages in dist/')
